// ============================================================
/** Fills zero-valued fields in dst from src. dst takes precedence. */
export function mergeWatchDashboardRequest(
  dst: WatchDashboardRequest,
  src: WatchDashboardRequest,
): void {
  if (dst.intervalSeconds === 0) {
    dst.intervalSeconds = src.intervalSeconds;
  }
}
