// ============================================================
// Merge: DashboardResponse
// ============================================================
/** Fills zero-valued fields in dst from src. dst takes precedence. */
export function mergeDashboardResponse(
  dst: DashboardResponse,
  src: DashboardResponse,
): void {
  if (!dst.clusterInfo && src.clusterInfo) {
    dst.clusterInfo = src.clusterInfo;
  }
  if (!dst.clusterHealth && src.clusterHealth) {
    dst.clusterHealth = src.clusterHealth;
  }
  if (dst.nodeMetrics.length === 0) {
    dst.nodeMetrics = src.nodeMetrics;
  }
  if (dst.grpcStats.length === 0) {
    dst.grpcStats = src.grpcStats;
  }
  if (dst.persistenceStatus.length === 0) {
    dst.persistenceStatus = src.persistenceStatus;
  }
  if (dst.networkStats.length === 0) {
    dst.networkStats = src.networkStats;
  }
  if (dst.threadInfo.length === 0) {
    dst.threadInfo = src.threadInfo;
  }
  if (dst.tokenCacheStats.length === 0) {
    dst.tokenCacheStats = src.tokenCacheStats;
  }
  if (dst.mapStats.length === 0) {
    dst.mapStats = src.mapStats;
  }
}
